#define FULL_MASK 0xffffffffu
__inline__ __device__ float warp_sum(float v) {
  v += __shfl_xor_sync(FULL_MASK, v, 16);
  v += __shfl_xor_sync(FULL_MASK, v, 8);
  v += __shfl_xor_sync(FULL_MASK, v, 4);
  v += __shfl_xor_sync(FULL_MASK, v, 2);
  v += __shfl_xor_sync(FULL_MASK, v, 1);
  return v;
}

// kernel1: each block handles a contiguous chunk of one row; int indexing
__global__ void k1(const float4* __restrict__ x, float* __restrict__ partials,
                   int n4, int nb, int chunks_per_block) {
  const int row = blockIdx.y;
  const float4* xr = x + (long)row * n4;
  float s = 0.f, q = 0.f;
  const int base = blockIdx.x * chunks_per_block;
  #pragma unroll 4
  for (int c = 0; c < chunks_per_block; ++c) {
    int i = (base + c) * blockDim.x + threadIdx.x;
    if (i < n4) {
      float4 v = xr[i];
      s += v.x + v.y + v.z + v.w;
      q += v.x*v.x + v.y*v.y + v.z*v.z + v.w*v.w;
    }
  }
  s = warp_sum(s); q = warp_sum(q);
  __shared__ float sh[2][32];
  int lane = threadIdx.x & 31, warp = threadIdx.x >> 5;
  int nw = blockDim.x >> 5;
  if (lane == 0) { sh[0][warp] = s; sh[1][warp] = q; }
  __syncthreads();
  if (warp == 0) {
    float a = lane < nw ? sh[0][lane] : 0.f;
    float b = lane < nw ? sh[1][lane] : 0.f;
    a = warp_sum(a); b = warp_sum(b);
    if (lane == 0) {
      partials[(long)row * 2 * nb + blockIdx.x] = a;
      partials[(long)row * 2 * nb + nb + blockIdx.x] = b;
    }
  }
}

// kernel2: elementwise style like torch copy, int indexing, ILP via unroll
__global__ void k2(const float4* __restrict__ x, const float4* __restrict__ w,
                   const float4* __restrict__ b, float4* __restrict__ y,
                   const float* __restrict__ partials, int n4, int nb, float eps) {
  const int row = blockIdx.y;
  float s = 0.f, q = 0.f;
  for (int i = threadIdx.x; i < nb; i += blockDim.x) {
    s += partials[(long)row * 2 * nb + i];
    q += partials[(long)row * 2 * nb + nb + i];
  }
  s = warp_sum(s); q = warp_sum(q);
  __shared__ float sh[2][32];
  __shared__ float sh_mean, sh_rstd;
  int lane = threadIdx.x & 31, warp = threadIdx.x >> 5;
  int nw = blockDim.x >> 5;
  if (lane == 0) { sh[0][warp] = s; sh[1][warp] = q; }
  __syncthreads();
  if (warp == 0) {
    float a = lane < nw ? sh[0][lane] : 0.f;
    float bb = lane < nw ? sh[1][lane] : 0.f;
    a = warp_sum(a); bb = warp_sum(bb);
    if (lane == 0) {
      float mean = a / (float)(n4 * 4);
      float var = bb / (float)(n4 * 4) - mean * mean;
      sh_mean = mean;
      sh_rstd = rsqrtf(var + eps);
    }
  }
  __syncthreads();
  const float mean = sh_mean, rstd = sh_rstd;
  const float4* xr = x + (long)row * n4;
  float4* yr = y + (long)row * n4;
  const int chunks = (n4 + blockDim.x - 1) / blockDim.x;
